24	// ParserWorker consumes raw messages and produces parsed messages.
25	type ParserWorker struct {
26		bus      eventbus.Bus
27		profiles *template.Loader
28	}
29	
30	// NewParserWorker creates a new parser worker.
31	func NewParserWorker(bus eventbus.Bus, profiles *template.Loader) *ParserWorker {
32		return &ParserWorker{bus: bus, profiles: profiles}
33	}
34	
35	// Start subscribes to raw messages and starts parsing.
36	func (w *ParserWorker) Start() error {
37		return w.bus.Subscribe("ingest.raw", w.handleRawMessage)
38	}
39	
40	func (w *ParserWorker) handleRawMessage(ctx context.Context, msg eventbus.Message) error {
41		var raw domain.RawMessage
42		if err := json.Unmarshal(msg.Payload, &raw); err != nil {
43			log.Printf("[Parser] Failed to unmarshal raw message: %v", err)
44			return err
45		}
46	
47		// Validate by attempting to parse (but store raw data for pipeline)
48		switch raw.Protocol {
49		case domain.ProtoASTM:
50			if _, err := astm.Parse(raw.Data); err != nil {
51				log.Printf("[Parser] ASTM parse error: %v", err)
52				return err
53			}
54		case domain.ProtoHL7:
55			if _, err := hl7parser.Parse(raw.Data); err != nil {
56				log.Printf("[Parser] HL7 parse error: %v", err)
57				return err
58			}
59		}
60	
61		parsed := domain.ParsedMessage{
62			RawMessageID:  raw.ID,
63			Protocol:      raw.Protocol,
64			CorrelationID: raw.ID,
65			ParsedAt:      time.Now(),
66			RawData:       raw.Data,
67		}
68	
69		return w.bus.Publish(ctx, "pipeline.parsed", parsed)
70	}
