42		}
43		if ext.AbnormalFlag != "" {
44			data.AbnormalFlag = e.resolveASTMPath(msg, ext.AbnormalFlag, "1")
45		}
46		if ext.ResultStatus != "" {
47			data.ResultStatus = e.resolveASTMPath(msg, ext.ResultStatus, "1")
48		}
49		if ext.DateTime != "" {
50			data.DateTime = e.resolveASTMPath(msg, ext.DateTime, "1")
51		}
