112	// resolveASTMPath resolves a path expression against an ASTM message.
113	func (e *Extractor) resolveASTMPath(msg *astm.Message, path string, defaultSegIdx string) string {
114		fp, err := ParsePath(path)
115		if err != nil {
116			return ""
117		}
118	
119		segIdx := fp.SegmentIdx
120		if segIdx == "" || segIdx == "*" {
121			segIdx = defaultSegIdx
122		}
123	
124		idx, _ := strconv.Atoi(segIdx)
125	
126		var seg *astm.Segment
127		segType := astm.SegmentType(fp.Segment)
128	
129		if fp.SegmentIdx == "*" {
130			// Wildcard: get first matching segment
131			segs := msg.SegmentsByType(segType)
132			if len(segs) == 0 {
133				return ""
134			}
135			seg = segs[0]
136		} else {
137			// Specific index: get nth segment
138			allSegs := msg.SegmentsByType(segType)
139			if idx < 1 || idx > len(allSegs) {
140				// For single segment lookup, try the standard method
141				seg = msg.SegmentByType(segType)
142			} else {
143				seg = allSegs[idx-1]
144			}
145		}
146	
147		if seg == nil {
148			return ""
149		}
