24	// MapObservation converts a single extracted result into a canonical Observation.
25	func (m *Mapper) MapObservation(data *template.ExtractedData) (*canonical.Observation, error) {
26		testCode := data.TestCode
27		tc := m.profile.Mapping.GetTestMapping(testCode)
28		if tc == nil {
29			// Fallback: use test code as-is
30			tc = &template.TestCodeMapping{
31				LOINC:    testCode,
32				LongName: testCode,
33				UCUM:     data.Unit,
34			}
35		}
36	
37		obs := canonical.NewObservation(tc.LOINC, tc.LongName)
38	
39		// Set value
40		if data.Value != "" {
41			if val, err := strconv.ParseFloat(data.Value, 64); err == nil {
42				unit := data.Unit
43				if unit == "" {
44					unit = tc.UCUM
45				}
46				// Apply unit conversion if needed
47				converted, convertedUnit, err := m.convertUnit(val, unit, tc.UCUM)
48				if err == nil {
49					obs.SetValue(converted, convertedUnit)
50				} else {
51					obs.SetValue(val, unit)
52				}
53			} else {
54				// Non-numeric value (e.g., "Positive", "Yellow")
55				obs.SetValueString(data.Value)
56			}
57		}
58	
59		// Set interpretation (abnormal flag)
60		if data.AbnormalFlag != "" {
61			obs.SetInterpretation(data.AbnormalFlag, m.interpretFlag(data.AbnormalFlag))
62		}
63	
64		// Set effective date/time
65		if data.DateTime != "" {
66			obs.EffectiveDateTime = data.DateTime
67		}
68	
69		// Mark as final if status indicates
70		if data.ResultStatus == "F" || data.ResultStatus == "final" {
71			obs.Finalize()
72		}
73	
74		return obs, nil
75	}
