77	// MapToReport converts a set of extracted results into a DiagnosticReport.
78	func (m *Mapper) MapToReport(results []*template.ExtractedData, sampleID string) (*canonical.DiagnosticReport, error) {
79		report := canonical.NewDiagnosticReport()
80	
81		if sampleID != "" {
82			specimen := canonical.NewSpecimen(sampleID)
83			specimen.AddIdentifier("http://hub-lab/specimen", sampleID)
84			report.Specimen = append(report.Specimen, canonical.Reference{
85				Reference: fmt.Sprintf("Specimen/%s", specimen.ID),
86				Type:      "Specimen",
87			})
88		}
89	
